from pathlib import Path
import base64,gzip,hashlib,sys
PAYLOAD=""
if len(PAYLOAD)!=3952: raise RuntimeError(f"payload length mismatch: {len(PAYLOAD)}")
if hashlib.sha256(PAYLOAD.encode("ascii")).hexdigest()!="c9875c673bc16260c8f823f5cecd22cfd4c820c39814fe0a8b328025ed07b8cd":
    raise RuntimeError("payload hash mismatch")
source=gzip.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(source).hexdigest()!="14d28702255c05e0a5e7d08c14d4d54a1ced1201f0b14ae99fe9533842a5a464":
    raise RuntimeError("source hash mismatch")
exec(compile(source,"ui-audit-fix-round2","exec"))
